def GaussianUnitProjectionLaw : Prop :=
  ∀ (m : ℕ) (v : Source.Space m), ‖v‖ = 1 →
    (standardGaussian m).map (fun z => inner ℝ z v) = gaussianReal 0 1

def GaussianPairReconstructionLaw : Prop :=
  ∀ m n : ℕ, ((standardGaussian m).prod (vectorMarkLaw m n)).map
    (reconstruction m n) = gaussianIid m (n+2)

def GaussianCDFTangentInput : Prop :=
  ∀ (K : ℕ) (b t : ℝ), 0 < Φ b → t ≤ b →
    Φ t ^ K ≤ Φ b ^ K * Real.exp ((K : ℝ)*φ b/Φ b*(t-b))

def CauchyPerimeterLaw : Prop :=
  ∀ (K : ℕ) (hK : 0 < K) (Z : Cloud K),
    perimeter (hull Z) = ∫ t in Icc 0 (2*Real.pi), support hK Z t
